"""Paired cost ablations and full-resolution inspection, with an explicit oracle boundary."""
import json
import statistics as st
from pathlib import Path
ROOT = Path('artifacts/appearance-probe/regional-efficiency')

def summarize(data):
    out=[]
    for resolution in [0,1]:
        rows=[r for r in data['rows'] if r['resolution']==resolution]
        timed=[r for r in rows if r['timings']]
        def pair(row,mode,key):
            return st.mean(row['timings'][i][key]['median'] for i in [mode,mode+6])
        modes=[]
        for mode,name in enumerate(data['modes']):
            modes.append({'name':name,'medians':{key:st.median(pair(r,mode,key) for r in timed) for key in ['gpu_ms','serial_ms','throughput_ms','planning_us','upload_ms','encode_ms']},'relative_grouped_full':{key:st.median(pair(r,mode,key)/pair(r,3,key) for r in timed) for key in ['gpu_ms','serial_ms','throughput_ms']},'relative_old_regional':{key:st.median(pair(r,mode,key)/pair(r,1,key) for r in timed) for key in ['gpu_ms','serial_ms','throughput_ms','planning_us']},'duplicate_control_ratio_range':{key:[min(r['timings'][mode+6][key]['median']/r['timings'][mode][key]['median'] for r in timed),max(r['timings'][mode+6][key]['median']/r['timings'][mode][key]['median'] for r in timed)] for key in ['gpu_ms','serial_ms','throughput_ms']}})
        out.append({'resolution':resolution,'modes':modes,'selection_same':True,'max_optimized_vs_old_rmse':max(r['quality']['optimized_vs_old']['foreground_rmse'] for r in rows),'max_full_batch_rmse':max(r['quality']['grouped_full_vs_full']['foreground_rmse'] for r in rows),'old_draws':[min(r['counts'][1]['draw_calls'] for r in rows),max(r['counts'][1]['draw_calls'] for r in rows)],'new_draws':[min(r['counts'][4]['draw_calls'] for r in rows),max(r['counts'][4]['draw_calls'] for r in rows)],'oracle_triangle_fraction_median':st.median(r['oracle']['counts']['triangles']/r['counts'][0]['triangles'] for r in timed),'oracle_discovery_ms_median':st.median(r['oracle']['discovery_cpu_gpu_readback_scan_ms'] for r in timed),'oracle_stale_rmse_max':max(r['oracle']['stale_previous_sample_error']['foreground_rmse'] for r in timed if r['oracle']['stale_previous_sample_error'])})
    return out

def main():
    data=json.loads((ROOT/'report.json').read_text());data['summary']=summarize(data)
    (ROOT/'summary.json').write_text(json.dumps(data['summary'],indent=2))
    # Keep the interactive payload small: raw benchmark samples stay in report.json.
    for r in data['rows']:
        r['timings']=[{k:v for k,v in t.items() if k in ['mode','serial_ms','gpu_ms','throughput_ms','planning_us']} for t in r['timings']] if r['timings'] else None
        for c in r['counts']:c.pop('per_object',None)
    html='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ignis · custo e visibilidade</title>
<style>*{box-sizing:border-box}body{margin:30px auto;max-width:1600px;padding:0 24px;background:#101720;color:#e4edf4;font:15px/1.5 system-ui}h1{font-size:32px}h2{font-size:20px}.panel{background:#172231;padding:20px;border:1px solid #34465b;border-radius:12px;margin:20px 0}.controls{display:flex;flex-wrap:wrap;gap:18px;align-items:center}button,select{font:inherit;background:#263b52;color:inherit;border:1px solid #4c6885;border-radius:6px;padding:8px}button{cursor:pointer}input{width:min(600px,80vw)}.overview{display:grid;grid-template-columns:1fr 1fr;gap:16px}.overview canvas{width:100%;height:auto;cursor:crosshair}.crops{display:flex;gap:14px;flex-wrap:wrap}.crops canvas{image-rendering:pixelated;max-width:none}.scroll{overflow:auto}figure{margin:0}figcaption{font-weight:600;margin-bottom:8px}.note{color:#aec0cf;font-size:13px}.stat{color:#f1c791}table{border-collapse:collapse;min-width:700px}td,th{padding:8px 16px 8px 0;text-align:left;border-bottom:1px solid #34465b}@media(max-width:850px){.overview{grid-template-columns:1fr}}</style>
<body><p class="stat">IGNIS · EAF-75 · INVESTIGAÇÃO GRÁFICA</p><h1>Quanto custa aquilo que aparece?</h1><p>Mesma cena de 96 objetos e terreno. Seleção mais barata e desenhos agrupados, comparados com geometria completa também agrupada. A imagem regional é verificada contra o experimento anterior.</p>
<div class="panel controls"><label>Render físico <select id="resolution"><option value="0">3456 × 2234</option><option value="1">1728 × 1117</option></select></label><button id="play">Reproduzir percurso</button><button id="mixed">Inspecionar mistura visível</button><label>Recorte <select id="zoom"><option value="1">1× físico</option><option value="2">2×</option><option value="4">4×</option></select></label><input id="frame" type="range" min="0" max="25" value="6"></div>
<p id="pose" class="stat"></p><p id="status"></p><div id="overview" class="overview"></div><p class="note">Visões gerais reduzidas para caber. Clique para comparar o mesmo recorte físico abaixo. Reprodução de capturas offline; não é a engine rodando no navegador.</p>
<div class="panel"><p id="focus"></p><div class="scroll"><div id="crops" class="crops"></div></div><p id="display" class="note"></p></div>
<div class="panel"><h2>Qualidade e custo nesta posição</h2><p id="quality"></p><p id="counts"></p><p id="oracle"></p><div class="scroll"><table id="timings"></table></div></div>
<div class="panel"><h2>Resultado do percurso</h2><div class="scroll"><table id="summary"></table></div><p class="note">Razões pareadas por câmera; 100% é o custo da geometria completa agrupada. Menor é melhor. Cada representação tem controles duplicados e ordem rotacionada. GPU mede o passe; serial inclui seleção, upload, codificação, submissão e espera. Vazão mede blocos de 8 frames enfileirados na mesma pose, com CPU/GPU sobrepostas: não mede latência de entrada nem FPS de um jogo. Posições com medição a cada três passos; ida e volta.</p><p id="noise" class="note"></p></div>
<div class="panel"><h2>O limite ideal ainda não é um algoritmo utilizável</h2><p>O controle “Visibilidade ideal” conserva apenas regiões da geometria que ganharam pixels no frame completo. Ele não usa resumos e serve para estimar a oportunidade de remover trabalho oculto. Descobrir essa máscara exigiu desenhar tudo e ler os IDs de volta; esse custo aparece separado e não está incluído na linha ideal da tabela. A máscara vale para aquela câmera e amostragem. Ao reutilizá-la depois de mover a câmera, partes recém-visíveis desaparecem.</p><p>O caminho utilizável desta rodada mantém as decisões anteriores: substitui projeções repetidas por limites analíticos conservadores, agrupa faixas iguais e conserva os mesmos materiais, resumos e profundidade. Menos chamadas não garante menos trabalho GPU; os controles medem isso. O cache de aproximadamente30MiB continua compartilhado entre instâncias.</p><p>Erro adicional zero contra a versão anterior não significa imagem perfeita: continuam as limitações de silhueta, cobertura e materiais do cache. Regiões brilhantes permanecem geométricas. Não há sombra projetada, reflexão indireta, GI, vento ou deformação; uma superfície fora da câmera ainda pode contribuir por esses caminhos num jogo completo.</p></div>
<script>
const DATA=__DATA__;const $=id=>document.getElementById(id);const labels=['Geometria original','Regional anterior','Seleção rápida','Geometria agrupada','Regional agrupado','Visibilidade ideal · offline'];let epoch=0,loaded=null,focus=[.5,.5],focusId=null,interval=null;
const fmt=(v,n=3)=>Number(v).toFixed(n),rows=()=>DATA.rows.filter(r=>r.resolution===Number($('resolution').value)),current=()=>rows()[Number($('frame').value)];
function row(values,head=false){const tr=document.createElement('tr');for(const value of values){const cell=document.createElement(head?'th':'td');cell.textContent=String(value);tr.append(cell)}return tr}
function crop(){if(!loaded)return;const r=current(),z=Number($('zoom').value),dpr=window.devicePixelRatio||1,o=r.visible_regions.find(o=>o.id===focusId);if(o)focus=[(o.bbox[0]+o.bbox[2])/2/r.size[0],(o.bbox[1]+o.bbox[3])/2/r.size[1]];const side=512,x=Math.round(Math.max(0,Math.min(r.size[0]-side,focus[0]*r.size[0]-side/2))),y=Math.round(Math.max(0,Math.min(r.size[1]-side,focus[1]*r.size[1]-side/2)));$('crops').replaceChildren(...loaded.map((img,i)=>{const f=document.createElement('figure'),cap=document.createElement('figcaption'),c=document.createElement('canvas');cap.textContent=['Geometria completa','Regional otimizado','Mapa: geometria azul / resumo laranja','Visibilidade ideal · offline'][i];c.width=side;c.height=side;c.style.width=`${side*z/dpr}px`;c.style.height=`${side*z/dpr}px`;c.getContext('2d').drawImage(img,x,y,side,side,0,0,side,side);f.append(cap,c);return f}));$('focus').textContent=o?`Objeto ${o.id}: ${o.geometry_pixels} pixels de geometria + ${o.summary_pixels} de resumo visíveis.`:'Recorte escolhido na cena.';$('display').textContent=`Recorte físico512² em (${x}, ${y}); DPR ${dpr}, ampliação ${z}×, lado CSS ${fmt(side*z/dpr,1)}px.`;}
function show(){const r=current(),e=++epoch;$('frame').max=rows().length-1;loaded=null;$('pose').textContent=`${r.frame<13?'Afastando':'Retornando'} · posição ${r.frame+1}/26 · câmera (${r.eye.map(v=>fmt(v,1)).join(', ')})`;$('quality').textContent=`Erro RGB foreground adicional versus regional anterior: ${fmt(r.quality.optimized_vs_old.foreground_rmse,8)}; IDs divergentes: ${r.quality.optimized_vs_old.id_mismatch_pixels}. Erro do regional contra geometria: ${fmt(r.quality.optimized_vs_full.foreground_rmse,5)}.`;$('counts').textContent=`Desenhos: regional ${r.counts[1].draw_calls} → ${r.counts[4].draw_calls}; geometria ${r.counts[0].draw_calls} → ${r.counts[3].draw_calls}. Triângulos do regional preservados: ${r.counts[4].triangles.toLocaleString('pt-BR')}.`;
 const o=r.oracle;$('oracle').textContent=o?`Visibilidade ideal: ${fmt(100*(1-o.counts.triangles/r.counts[0].triangles),1)}% menos triângulos da geometria; erro foreground ${fmt(o.error_vs_full.foreground_rmse,8)}. Obter a máscara custou ${fmt(o.discovery_cpu_gpu_readback_scan_ms,2)}ms (CPU, GPU, readback e scan). ${o.stale_previous_sample_error?'Máscara da posição amostrada anterior: erro '+fmt(o.stale_previous_sample_error.foreground_rmse,5)+'.':''}`:'Visibilidade ideal e cronômetros disponíveis a cada três passos.';
 $('timings').replaceChildren(row(['Representação','GPU ms','Serial ms','Vazão ms/frame','Seleção µs'],true));if(r.timings){for(let m=0;m<6;m++){const avg=k=>(r.timings[m][k].median+r.timings[m+6][k].median)/2;$('timings').append(row([labels[m],fmt(avg('gpu_ms')),fmt(avg('serial_ms')),fmt(avg('throughput_ms')),fmt(avg('planning_us'),1)]))}}
 const s=DATA.summary[Number($('resolution').value)];$('summary').replaceChildren(row(['Representação','GPU / geom. agrupada','Serial / geom. agrupada','Vazão / geom. agrupada','CPU µs'],true),...s.modes.map((m,i)=>row([labels[i],fmt(m.relative_grouped_full.gpu_ms*100,1)+'%',fmt(m.relative_grouped_full.serial_ms*100,1)+'%',fmt(m.relative_grouped_full.throughput_ms*100,1)+'%',fmt(m.medians.planning_us,1)])));const noise=s.modes[4].duplicate_control_ratio_range;$('noise').textContent=`Controle regional duplicado, razão entre medianas por pose: GPU ${noise.gpu_ms.map(x=>fmt(x,2)).join('–')}; serial ${noise.serial_ms.map(x=>fmt(x,2)).join('–')}; vazão ${noise.throughput_ms.map(x=>fmt(x,2)).join('–')}. Valores distantes de1 indicam variação; ganhos pequenos exigem cautela.`;
 $('status').textContent='Carregando capturas…';const files=['full','optimized','map',...(o?['oracle']:[])];Promise.all(files.map(key=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=reject;img.src=`${r.id}_${key}.png`;}))).then(images=>{if(e!==epoch)return;loaded=images;$('overview').replaceChildren(...images.slice(0,2).map((img,i)=>{const f=document.createElement('figure'),cap=document.createElement('figcaption'),c=document.createElement('canvas');cap.textContent=['Geometria completa','Regional otimizado'][i];c.width=r.size[0];c.height=r.size[1];c.getContext('2d').drawImage(img,0,0);c.onpointerdown=ev=>{const rect=c.getBoundingClientRect();focus=[(ev.clientX-rect.left)/rect.width,(ev.clientY-rect.top)/rect.height];focusId=null;crop()};f.append(cap,c);return f}));$('status').textContent='';crop()}).catch(()=>{if(e===epoch)$('status').textContent='Falha ao carregar uma captura.'});}
$('resolution').onchange=show;$('frame').oninput=show;$('zoom').onchange=crop;window.addEventListener('resize',crop);$('mixed').onclick=()=>{const o=current().visible_regions.filter(o=>o.geometry_pixels&&o.summary_pixels).sort((a,b)=>b.geometry_pixels+b.summary_pixels-a.geometry_pixels-a.summary_pixels)[0];if(o){focusId=o.id;crop()}};$('play').onclick=()=>{if(interval){clearInterval(interval);interval=null;$('play').textContent='Reproduzir percurso'}else{interval=setInterval(()=>{$('frame').value=String((Number($('frame').value)+1)%26);show()},500);$('play').textContent='Pausar'}};show();
</script></body></html>'''
    (ROOT/'index.html').write_text(html.replace('__DATA__',json.dumps(data,separators=(',',':'))))
    print(json.dumps(data['summary'],indent=2))
if __name__=='__main__':main()
